export type FinancialSummaryReportBalanceSheet = {
  /** Net of reconciled credits minus reconciled debits. */
  cashOnHand: number;
  /** Matched-but-not-yet-reconciled credits. */
  outstandingReceivables: number;
  unpaidBills: number;
  unreimbursedExpenses: number;
  /** Ledger-source: net debit balance of asset accounts with subtype
'cash' as of toDate. Operational source: mirrors cashOnHand.
 */
  cash: number;
  /** Ledger-source: net debit balance of asset accounts with subtype
'ar'. Operational source: mirrors outstandingReceivables.
 */
  accountsReceivable: number;
  /** Ledger-source: net debit balance of all remaining asset
accounts (everything not classified as cash or AR, including
contra-asset accounts). Operational source: 0.
 */
  otherAssets: number;
  /** Ledger-source: net credit balance of liability accounts with
subtype 'ap'. Operational source: mirrors unpaidBills.
 */
  accountsPayable: number;
  /** Ledger-source: net credit balance of all remaining liability
accounts (including contra-liability). Operational source:
mirrors unreimbursedExpenses.
 */
  otherLiabilities: number;
  totalAssets: number;
  totalLiabilities: number;
  equity: number;
  /** Equity carried forward from periods strictly before fromDate.
Computed as `equity - currentPeriodNetIncome` so the three
equity rows always reconcile to assets − liabilities.
 */
  openingNetAssets: number;
  /** Net income for the selected period (totalIncome −
totalExpenses). The change in net assets contributed by
activity inside [fromDate, toDate].
 */
  currentPeriodNetIncome: number;
  /** Per-CoA-account rows that sum to the `cash` total (ledger
source). Empty for the operational source.
 */
  cashAccounts: BalanceSheetAccount[];
  /** Per-account rows summing to `accountsReceivable`. */
  accountsReceivableAccounts: BalanceSheetAccount[];
  /** Per-account rows summing to `otherAssets`. */
  otherAssetAccounts: BalanceSheetAccount[];
  /** Per-account rows summing to `accountsPayable`. */
  accountsPayableAccounts: BalanceSheetAccount[];
  /** Per-account rows summing to `otherLiabilities`. */
  otherLiabilityAccounts: BalanceSheetAccount[];
};

